1	/**
2	 * Angular CLI workspace and TypeScript configuration migration.
3	 *
4	 * The shapes handled here are the ones the Angular CLI itself defines and the
5	 * ones the modern `@angular-devkit/build-angular` schema no longer accepts. No
6	 * capability branches on a project name, an application name or a source
7	 * string: every project in `angular.json` is walked, whatever it is called.
8	 *
9	 * Both entry points parse strict JSON. A configuration carrying comments
10	 * (JSONC, which the CLI also accepts) is refused with a diagnosable error
11	 * rather than silently reserialized, because rewriting it would delete the
12	 * comments without saying so.
13	 */
14	
15	import { REMOVED_BUILDER_PACKAGES, compareStrings } from './angular-target-cell.ts';
16	import type { AngularTargetCell } from './angular-target-cell.ts';
17	import {
18		WRAPPER_BUILDER_REPLACEMENTS,
19		WRAPPER_ONLY_OPTIONS,
20		analyzeCustomWebpackFragment,
21		builderPackageOf,
22		type WebpackFragmentAnalysis,
23	} from './custom-webpack-absorption.ts';
24	import {
25		isTslintBuilder,
26		targetLineDropsTslint,
27		tslintTargetRemoval,
28	} from './tslint-toolchain-removal.ts';
29	
30	export type ConfigChange = Readonly<{ path: string; from: string | null; to: string | null }>;
31	
32	export type WorkspaceMigration = Readonly<{
33		config: string;
34		changes: readonly ConfigChange[];
35		removedPackages: readonly string[];
36		unhandled: readonly string[];
37		/**
38		 * Webpack fragments that are no longer referenced by any target, because the
39		 * wrapper builder that read them was absorbed back into the official builder.
40		 */
41		absorbedFragments: readonly WebpackFragmentAnalysis[];
42		/**
43		 * Capabilities the migrated workspace deliberately no longer has, one line
44		 * per removal. Distinct from {@link WorkspaceMigration.unhandled}: these are
45		 * decisions the cell declared, not shapes the migration could not read.
46		 */
47		declaredDifferences: readonly string[];
48	}>;
49	
50	/**
51	 * Webpack fragments a wrapper builder may reference, keyed by the path the
52	 * workspace writes for them. A referenced fragment that is not supplied here
53	 * cannot be read, and an unread fragment is never absorbed.
54	 */
55	export type WebpackFragmentSources = Readonly<Record<string, string>>;
56	
57	export type JsonObject = Record<string, unknown>;
58	
59	/**
60	 * Builder options the modern devkit schema no longer accepts. A build fails
61	 * outright on an unknown option, so leaving one in place is not a cosmetic
62	 * defect.
63	 *
64	 * `extractCss` was removed once CSS extraction became unconditional in
65	 * production; `es5BrowserSupport` and `showCircularDependencies` went with the
66	 * differential-loading and webpack-plugin surfaces they configured;
67	 * `experimentalRollupPass` and `lazyModules` were experimental options the
68	 * devkit dropped. `evalSourceMap` and `vendorSourceMap` were the two sibling
69	 * booleans that sat beside `sourceMap` before the devkit replaced the trio with
70	 * a single `sourceMap` object carrying `scripts`, `styles`, `vendor` and
71	 * `hidden`; the object form is what the modern schema accepts and the loose
72	 * booleans are what it rejects.
73	 *
74	 * Each name here was read off a build that stopped on it: the schema validator
75	 * runs before the compiler, so one surviving option is not a warning but the
76	 * whole build — `Data path "" must NOT have additional properties(evalSourceMap)`
77	 * and nothing else.
78	 */
79	export const REMOVED_BUILDER_OPTIONS: readonly string[] = Object.freeze([
80		'es5BrowserSupport',
81		'evalSourceMap',
82		'experimentalRollupPass',
83		'extractCss',
84		'lazyModules',
85		'showCircularDependencies',
86		'vendorSourceMap',
87	]);
88	
89	/**
90	 * Builders the modern devkit no longer ships at all. The target that uses one
91	 * cannot be carried across the hop: it is removed, and the packages it existed
92	 * to run are reported so the manifest alignment can drop them too. Replacing
93	 * the capability the target provided (a linter, an end-to-end runner) is a
94	 * decision about the project, not a mechanical rewrite, so this capability
95	 * makes no attempt at one and says so.
96	 */
97	export const REMOVED_BUILDERS: readonly string[] = Object.freeze(
98		Object.keys(REMOVED_BUILDER_PACKAGES).sort(compareStrings),
99	);
100	
101	/** Builders this capability recognises as still present on a modern line. */
102	export const CARRIED_BUILDERS: readonly string[] = Object.freeze([
103		'@angular-devkit/build-angular:browser',
104		'@angular-devkit/build-angular:dev-server',
105		'@angular-devkit/build-angular:extract-i18n',
106		'@angular-devkit/build-angular:karma',
107		'@angular-devkit/build-angular:ng-packagr',
108		'@angular-devkit/build-angular:server',
109	]);
110	
111	/**
112	 * True when the document carries a `//` or `/* … *\/` comment outside a string
113	 * literal. String contents are skipped, because a JSON string legitimately
114	 * holds both sequences — a glob such as `**\/node_modules/**` and a URL both
115	 * do — and treating those as comments would refuse a strict JSON document.
116	 */
117	export function carriesJsonComment(source: string): boolean {
118		let inString = false;
119		for (let index = 0; index < source.length; index += 1) {
120			const character = source[index];
121			if (inString) {
122				if (character === '\\') index += 1;
123				else if (character === '"') inString = false;
124				continue;
125			}
126			if (character === '"') {
127				inString = true;
128				continue;
129			}
130			if (character !== '/') continue;
131			const next = source[index + 1];
132			if (next === '/' || next === '*') return true;
133		}
134		return false;
135	}
136	
137	export function parseStrictJson(source: string, kind: string): JsonObject {
138		if (carriesJsonComment(source))
139			throw new Error(
140				`Angular ${kind} migration: the configuration appears to carry comments. ` +
141					'This capability rewrites strict JSON only; a JSONC configuration would lose ' +
142					'its comments silently, so it is refused instead.',
143			);
144		const parsed: unknown = JSON.parse(source);
145		if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))
146			throw new Error(`Angular ${kind} migration: the configuration is not a JSON object`);
147		return parsed as JsonObject;
148	}
149	
150	export function serializeJson(value: unknown): string {
151		return `${JSON.stringify(value, null, 2)}\n`;
152	}
153	
154	const serialize = serializeJson;
155	
156	export function objectAt(value: unknown): JsonObject | null {
157		return typeof value === 'object' && value !== null && !Array.isArray(value)
158			? (value as JsonObject)
159			: null;
160	}
161	
162	/** `./webpack.config.js` and `webpack.config.js` name the same file. */
163	export function normalizeFragmentPath(value: string): string {
164		return value.startsWith('./') ? value.slice(2) : value;
165	}
166	
167	/** The fragment a wrapper target references, or null when it references none. */
168	function fragmentPathOf(target: JsonObject): string | null {
169		const options = objectAt(target['options']);
170		const declared = options === null ? undefined : objectAt(options['customWebpackConfig']);
171		const path = declared?.['path'];
172		return typeof path === 'string' ? normalizeFragmentPath(path) : null;
173	}
174	
175	type WrapperAbsorption = Readonly<{
176		/** True when every fragment any wrapper target references can be absorbed. */
177		absorbed: boolean;
178		analyses: readonly WebpackFragmentAnalysis[];
179		blockers: readonly string[];
180		/** Wrapper packages released once every one of their targets is absorbed. */
181		releasedPackages: readonly string[];
182	}>;
183	
184	/**
185	 * Decide, for the whole workspace at once, whether the wrapper builders can be
186	 * absorbed back into the official ones.
187	 *
188	 * The decision is workspace-wide rather than per target because the wrapper is
189	 * one dependency serving all of them, and because a wrapper target that names no
190	 * fragment of its own — a `dev-server` reading its browser target's — is only
191	 * absorbable if the fragment that target names is. Absorbing some targets and
192	 * not others would leave the package installed and the build half-migrated, so
193	 * one unreadable fragment refuses the lot.
194	 */
195	function planWrapperAbsorption(
196		projects: JsonObject,
197		fragments: WebpackFragmentSources,
198	): WrapperAbsorption {
199		const analyses = new Map<string, WebpackFragmentAnalysis>();
200		const blockers: string[] = [];
201		const releasedPackages = new Set<string>();
202		let sawWrapper = false;
203		for (const projectValue of Object.values(projects)) {
204			const project = objectAt(projectValue);
205			if (project === null) continue;
206			const architect = objectAt(project['architect']) ?? objectAt(project['targets']);
207			if (architect === null) continue;
208			for (const targetValue of Object.values(architect)) {
209				const target = objectAt(targetValue);
210				const builder = target === null ? null : target['builder'];
211				if (typeof builder !== 'string') continue;
212				const official = WRAPPER_BUILDER_REPLACEMENTS[builder];
213				if (official === undefined) continue;
214				sawWrapper = true;
215				const released = builderPackageOf(builder);
216				if (released !== null) releasedPackages.add(released);
217				const fragmentPath = target === null ? null : fragmentPathOf(target);
218				if (fragmentPath === null) continue;
219				if (analyses.has(fragmentPath)) continue;
220				const source = fragments[fragmentPath] ?? fragments[`./${fragmentPath}`];
221				if (source === undefined) {
222					blockers.push(
223						`${fragmentPath} is referenced by ${builder} but its contents were not supplied, ` +
224							'so what it adds to the build cannot be read and the wrapper was left in place',
225					);
226					continue;
227				}
228				analyses.set(fragmentPath, analyzeCustomWebpackFragment(fragmentPath, source, official));
229			}
230		}
231		for (const analysis of analyses.values())
232			if (!analysis.absorbable)
233				for (const blocker of analysis.blockers)
234					blockers.push(`${analysis.path}: ${blocker}`);
235		return Object.freeze({
236			absorbed: sawWrapper && blockers.length === 0,
237			analyses: Object.freeze([...analyses.values()]),
238			blockers: Object.freeze(blockers),
239			releasedPackages: Object.freeze([...releasedPackages].sort(compareStrings)),
240		});
241	}
242	
243	function migrateBuilderOptions(
244		options: JsonObject,
245		prefix: string,
246		changes: ConfigChange[],
247		wrapperAbsorbed: boolean,
248	): JsonObject {
249		const next: JsonObject = {};
250		for (const [key, value] of Object.entries(options)) {
251			if (wrapperAbsorbed && WRAPPER_ONLY_OPTIONS.includes(key)) {
252				changes.push({ path: `${prefix}.${key}`, from: JSON.stringify(value), to: null });
253				continue;
254			}
255			if (REMOVED_BUILDER_OPTIONS.includes(key)) {
256				changes.push({ path: `${prefix}.${key}`, from: JSON.stringify(value), to: null });
257				continue;
258			}
259			if (key === 'polyfills' && typeof value === 'string') {
260				next[key] = [value];
261				changes.push({
262					path: `${prefix}.polyfills`,
263					from: JSON.stringify(value),
264					to: JSON.stringify([value]),
265				});
266				continue;
267			}
268			next[key] = value;
269		}
270		return next;
271	}
272	
273	/**
274	 * Migrate an `angular.json` workspace onto the declared cell.
275	 *
276	 * Three mechanical changes, each one a shape the modern schema rejects: the
277	 * workspace-level `defaultProject` key, builder options the devkit removed
278	 * (in a target's `options` and in every named configuration), and the
279	 * `polyfills` option's string form, which became an array of entry points.
280	 * Targets whose builder no longer exists are removed and reported.
281	 */
282	export function migrateAngularWorkspace(
283		source: string,
284		cell: AngularTargetCell,
285		fragments: WebpackFragmentSources = {},
286	): WorkspaceMigration {
287		const workspace = parseStrictJson(source, 'workspace');
288		const changes: ConfigChange[] = [];
289		const removedPackages = new Set<string>();
290		const unhandled: string[] = [];
291		const declaredDifferences: string[] = [];
292		const next: JsonObject = {};
293		for (const [key, value] of Object.entries(workspace)) {
294			if (key === 'defaultProject') {
295				changes.push({ path: 'defaultProject', from: JSON.stringify(value), to: null });
296				continue;
297			}
298			if (key === 'cli') {
299				const cli = objectAt(value);
300				if (cli !== null && 'defaultCollection' in cli) {
301					const { defaultCollection, ...rest } = cli;
302					const collections =
303						typeof defaultCollection === 'string' ? [defaultCollection] : defaultCollection;
304					next[key] = { ...rest, schematicCollections: collections };
305					changes.push({
306						path: 'cli.defaultCollection',
307						from: JSON.stringify(defaultCollection),
308						to: null,
309					});
310					changes.push({
311						path: 'cli.schematicCollections',
312						from: null,
313						to: JSON.stringify(collections),
314					});
315					continue;
316				}
317			}
318			next[key] = value;
319		}
320		const projects = objectAt(next['projects']);
321		const absorption =
322			projects === null
323				? { absorbed: false, analyses: [], blockers: [], releasedPackages: [] }
324				: planWrapperAbsorption(projects, fragments);
325		unhandled.push(...absorption.blockers);
326		if (absorption.absorbed) for (const name of absorption.releasedPackages) removedPackages.add(name);
327		if (projects !== null) {
328			const migratedProjects: JsonObject = {};
329			for (const [projectName, projectValue] of Object.entries(projects)) {
330				const project = objectAt(projectValue);
331				if (project === null) {
332					migratedProjects[projectName] = projectValue;
333					continue;
334				}
335				const architect = objectAt(project['architect']) ?? objectAt(project['targets']);
336				if (architect === null) {
337					migratedProjects[projectName] = project;
338					continue;
339				}
340				const architectKey = objectAt(project['architect']) === null ? 'targets' : 'architect';
341				const migratedTargets: JsonObject = {};
342				for (const [targetName, targetValue] of Object.entries(architect)) {
343					const target = objectAt(targetValue);
344					let builder = target === null ? null : target['builder'];
345					const targetPath = `projects.${projectName}.${architectKey}.${targetName}`;
346					if (
347						absorption.absorbed &&
348						typeof builder === 'string' &&
349						WRAPPER_BUILDER_REPLACEMENTS[builder] !== undefined
350					) {
351						const official = WRAPPER_BUILDER_REPLACEMENTS[builder] as string;
352						changes.push({ path: `${targetPath}.builder`, from: builder, to: official });
353						builder = official;
354					}
355					if (
356						typeof builder === 'string' &&
357						isTslintBuilder(builder) &&
358						targetLineDropsTslint(cell)
359					) {
360						changes.push({ path: targetPath, from: builder, to: null });
361						for (const name of REMOVED_BUILDER_PACKAGES[builder] ?? [])
362							removedPackages.add(name);
363						declaredDifferences.push(tslintTargetRemoval(targetPath, builder, cell).reason);
364						continue;
365					}
366					if (typeof builder === 'string' && REMOVED_BUILDERS.includes(builder)) {
367						changes.push({ path: targetPath, from: builder, to: null });
368						for (const name of REMOVED_BUILDER_PACKAGES[builder] ?? [])
369							removedPackages.add(name);
370						unhandled.push(
371							`${targetPath} used ${builder}, which the ${cell.angularLine} devkit does not ship; ` +
372								'the target was removed and no replacement capability was chosen for it',
373						);
374						continue;
375					}
376					if (typeof builder === 'string' && !CARRIED_BUILDERS.includes(builder)) {
377						unhandled.push(
378							`${targetPath} uses ${builder}, which this capability does not recognise; ` +
379								'its options were left untouched',
380						);
381						migratedTargets[targetName] = targetValue;
382						continue;
383					}
384					if (target === null) {
385						migratedTargets[targetName] = targetValue;
386						continue;
387					}
388					const migratedTarget: JsonObject = { ...target, builder };
389					const options = objectAt(target['options']);
390					if (options !== null)
391						migratedTarget['options'] = migrateBuilderOptions(
392							options,
393							`${targetPath}.options`,
394							changes,
395							absorption.absorbed,
396						);
397					const configurations = objectAt(target['configurations']);
398					if (configurations !== null) {
399						const migratedConfigurations: JsonObject = {};
400						for (const [name, value] of Object.entries(configurations)) {
401							const configuration = objectAt(value);
402							migratedConfigurations[name] =
403								configuration === null
404									? value
405									: migrateBuilderOptions(
406											configuration,
407											`${targetPath}.configurations.${name}`,
408											changes,
409											absorption.absorbed,
410										);
411						}
412						migratedTarget['configurations'] = migratedConfigurations;
413					}
414					migratedTargets[targetName] = migratedTarget;
415				}
416				migratedProjects[projectName] = { ...project, [architectKey]: migratedTargets };
417			}
418			next['projects'] = migratedProjects;
419		}
420		return Object.freeze({
421			config: serialize(next),
422			changes: Object.freeze(changes),
423			removedPackages: Object.freeze([...removedPackages].sort(compareStrings)),
424			unhandled: Object.freeze(unhandled),
425			absorbedFragments: Object.freeze(absorption.absorbed ? absorption.analyses : []),
426			declaredDifferences: Object.freeze(declaredDifferences),
427		});
428	}
429	
430	export type TsConfigMigration = Readonly<{
431		config: string;
432		changes: readonly ConfigChange[];
433		unhandled: readonly string[];
434	}>;
435	
436	/**
437	 * Migrate a workspace `tsconfig.json` onto the declared cell.
438	 *
439	 * The Angular compiler on a modern line emits ES2022 output and requires
440	 * `useDefineForClassFields: false` at that target, because TypeScript's
441	 * standards-compliant class-field semantics would otherwise overwrite the
442	 * fields Angular's decorators initialise. `enableIvy` is removed: Ivy is the
443	 * only compiler left, and the option is no longer read.
444	 */
445	export function migrateAngularTsConfig(source: string, cell: AngularTargetCell): TsConfigMigration {
446		const config = parseStrictJson(source, 'tsconfig');
447		const changes: ConfigChange[] = [];
448		const unhandled: string[] = [];
449		const next: JsonObject = { ...config };
450		const compilerOptions = objectAt(config['compilerOptions']);
451		if (compilerOptions === null) {
452			unhandled.push('the tsconfig declares no compilerOptions; nothing was aligned');
453			return Object.freeze({
454				config: serialize(next),
455				changes: Object.freeze(changes),
456				unhandled: Object.freeze(unhandled),
457			});
458		}
459		const migrated: JsonObject = { ...compilerOptions };
460		for (const key of ['target', 'module'] as const) {
461			const from = compilerOptions[key];
462			if (from === 'ES2022') continue;
463			migrated[key] = 'ES2022';
464			changes.push({
465				path: `compilerOptions.${key}`,
466				from: from === undefined ? null : JSON.stringify(from),
467				to: '"ES2022"',
468			});
469		}
470		if (compilerOptions['useDefineForClassFields'] !== false) {
471			migrated['useDefineForClassFields'] = false;
472			changes.push({
473				path: 'compilerOptions.useDefineForClassFields',
474				from:
475					compilerOptions['useDefineForClassFields'] === undefined
476						? null
477						: JSON.stringify(compilerOptions['useDefineForClassFields']),
478				to: 'false',
479			});
480		}
481		next['compilerOptions'] = migrated;
482		const angularCompilerOptions = objectAt(config['angularCompilerOptions']);
483		if (angularCompilerOptions !== null && 'enableIvy' in angularCompilerOptions) {
484			const { enableIvy, ...rest } = angularCompilerOptions;
485			next['angularCompilerOptions'] = rest;
486			changes.push({
487				path: 'angularCompilerOptions.enableIvy',
488				from: JSON.stringify(enableIvy),
489				to: null,
490			});
491		}
492		unhandled.push(
493			`compilerOptions.lib was left as declared; the ${cell.angularLine} line does not require a specific lib set ` +
494				'and narrowing one could remove a type surface the application relies on',
495		);
496		return Object.freeze({
497			config: serialize(next),
498			changes: Object.freeze(changes),
499			unhandled: Object.freeze(unhandled),
500		});
501	}
