export type FontLocality = Readonly<{
	lane: string;
	/** The emitted document that was read. */
	emitted: string;
	/** The application's own source index.html, and what it links. */
	sourceLinks: readonly string[];
	/** Font-host URLs the *emitted* document carries. */
